import { ChangeDetectionStrategy, Component, OnInit, Inject, PLATFORM_ID } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { environment } from '../../../environments/environment';
import { LucideAngularModule } from 'lucide-angular';
import { TranslationService } from '../../core/services/translation.service';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'app-process',
  standalone: true,
  imports: [LucideAngularModule, TranslateModule],
  templateUrl: './process.component.html',
  styleUrl: './process.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ProcessComponent implements OnInit {
  baseUrl: any;
  constructor(public translationService: TranslationService,
    @Inject(DOCUMENT) private document: Document,
    @Inject(PLATFORM_ID) private platformId: Object,
  ) {
    this.baseUrl = environment.url;
  }

  ngOnInit(): void {
    this.addSchema();
    this.addBreadcrumbSchema();
    if (!isPlatformBrowser(this.platformId)) return;

    setTimeout(() => {
      window.scroll({
        top: 0,
        left: 0,
        behavior: 'smooth'
      });
    }, 500);
  }

  addSchema() {
    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "process-webpage-schema";
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "WebPage",
      "name": "Our Process",
      "description": "The creative process behind Pixtar's work.",
      "url": "https://www.pixtar.ae/process"
    });

    this.document.head.appendChild(script);
  }

  addBreadcrumbSchema() {
    const existingScript = this.document.getElementById("breadcrumb-schema-process");
    if (existingScript) return;

    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "breadcrumb-schema-process";

    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://www.pixtar.ae/"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "Process",
          "item": "https://www.pixtar.ae/process"
        }
      ]
    });

    this.document.head.appendChild(script);
  }
}
